for n,f,sub,expr,ran in [(1,x**3/sq(1+x*x),r'x=\tan\theta',r'\int\tan^3\theta\sec\theta\,d\theta',r'-\pi/2<\theta<\pi/2'),(2,x**3/sq(9-x*x),r'x=3\sin\theta',r'27\int\sin^3\theta\,d\theta',r'-\pi/2<\theta<\pi/2'),(3,x*x/sq(x*x-2),r'x=\sqrt2\sec\theta',r'2\int\sec^3\theta\,d\theta',r'0<\theta<\pi/2\ \text{or}\ \pi<\theta<3\pi/2'),(4,x**3/(9-4*x*x)**Q(3,2),r'x=(3/2)\sin\theta',r'\frac3{16}\int\frac{\sin^3\theta}{\cos^2\theta}d\theta',r'-\pi/2<\theta<\pi/2')]:
 add(n,(M(s.latex(s.Integral(f,x)))+'(a)삼각치환을 고르고 (b)삼각함수 적분으로 바꾸되 계산하지 마라.',M(s.latex(s.Integral(f,x)))+'(a)Choose a trigonometric substitution.(b)Transform the integral without evaluating it.'),fs(sub,ran,expr),same(M('(a)'+sub+r';\quad(b)'+expr)),('치환의 미분인자와 양의 제곱근을 확인했다. sec 치환의 두 각도 구간에서 secθ tanθ>0이다.','Checked the substitution differential and positive square root; secθ tanθ>0 on both secant-substitution angle intervals.'),['a','b'])
def integ(n,f,F,q,steps,lo=None,hi=None,pts=None):
 f,F=s.sympify(f),s.sympify(F);ff=s.lambdify(q,f.subs(a,2),'mpmath');FF=s.lambdify(q,F.subs(a,2),'mpmath')
 for pt in (pts or ['.2','.4']):
  z=mp.mpf(str(pt));assert abs(mp.diff(FF,z)-ff(z))<mp.mpf('1e-23')*max(1,abs(ff(z))),(n,z,mp.diff(FF,z),ff(z))
 I=s.Integral(f,q if lo is None else(q,lo,hi));ans=s.latex(F)+'+C';out=list(steps)+fs('F('+s.latex(q)+')='+s.latex(F))
 if lo is not None:
  val=s.simplify(F.subs(q,hi)-F.subs(q,lo));num=mp.quad(ff,[float(s.sympify(lo).subs(a,2)),float(s.sympify(hi).subs(a,2))]);assert abs(complex(val.subs(a,2).evalf())-complex(num))<1e-7*max(1,abs(complex(num))),(n,val,num)
  ans=s.latex(val);out+=fs(s.latex(I)+'=F('+s.latex(hi)+')-F('+s.latex(lo)+')='+ans)
 add(n,(M(s.latex(I))+'적분을 구하라.',M(s.latex(I))+'Evaluate the integral.'),out,same(M(ans)),('치환 범위에서 제곱근의 부호를 보존하고 원시함수의 독립 수치미분으로 확인했다. 정적분은 수치구적으로도 비교했다.','Preserved radical signs on the substitution interval and checked the primitive by independent numerical differentiation; definite integrals also cross-checked by quadrature.'));checks.append(n)
 return F
