rows=[(9,x**3*sq(16+x*x),(x*x+16)**Q(5,2)/5-Q(16,3)*(x*x+16)**Q(3,2),x,[r'u=16+x^2,\quad x^3dx=(u-16)du/2',r'\tfrac12\int(u^{3/2}-16u^{1/2})du'],None,None,None),(10,x*x/sq(9-x*x),Q(9,2)*asin(x/3)-x*sq(9-x*x)/2,x,[r'x=3\sin\theta,\quad\int x^2dx/\sqrt{9-x^2}=9\int\sin^2\theta d\theta'],None,None,None),(11,sq(x*x-1)/x**4,(x*x-1)**Q(3,2)/(3*x**3),x,[r'x=\sec\theta\quad(x>1),\quad\int\sin^2\theta\cos\theta d\theta=\sin^3\theta/3',r'\frac{(x^2-1)^{3/2}}{3x^3}\quad\text{also differentiates correctly for }x<-1'],None,None,['2','3','-2']),(12,x/sq(36-x*x),-sq(36-x*x),x,[r'u=36-x^2,\ du=-2x dx',r'-\tfrac12\int u^{-1/2}du=-\sqrt u'],0,3,None),(13,1/(a*a+x*x)**Q(3,2),x/(a*a*sq(a*a+x*x)),x,[r'x=a\tan\theta,\quad a>0',r'\frac1{a^2}\int\cos\theta d\theta=\sin\theta/a^2'],0,a,None),(14,1/(t*t*sq(t*t-16)),sq(t*t-16)/(16*t),t,[r't=4\sec\theta\quad(t>4)',r'\frac1{16}\int\cos\theta d\theta=\sin\theta/16'],None,None,['5','6','-5']),(15,1/(x*x-1)**Q(3,2),-x/sq(x*x-1),x,[r'x=\sec\theta,\quad\int\frac{\sec\theta}{\tan^2\theta}d\theta=\int\frac{\cos\theta}{\sin^2\theta}d\theta=-\csc\theta'],2,3,['2.2','2.7']),(16,sq(4-9*x*x),x*sq(4-9*x*x)/2+Q(2,3)*asin(3*x/2),x,[r'x=(2/3)\sin\theta',r'\frac43\int\cos^2\theta d\theta=\frac23(\theta+\sin\theta\cos\theta)'],0,Q(2,3),None),(17,x*sq(1-4*x*x),-(1-4*x*x)**Q(3,2)/12,x,[r'u=1-4x^2,\ du=-8x dx',r'-\tfrac18\int\sqrt udu=-u^{3/2}/12'],0,Q(1,2),None),(18,1/sq(4+t*t),log(t+sq(4+t*t)),t,[r't=2\tan\theta,\quad\int\sec\theta d\theta=\ln|\sec\theta+\tan\theta|'],0,2,None),(19,sq(x*x-9)/x**3,acos(3/s.Abs(x))/6-sq(x*x-9)/(2*x*x),x,[r'x=3\sec\theta\quad(x>3)',r'\tfrac13\int\sin^2\theta d\theta=\theta/6-\sin2\theta/12',r'\alpha=\arccos(3/|x|)\quad\text{extends the primitive to }x<-3'],None,None,['4','5','-4']),(20,1/(x*x+1)**2,x/(2*(1+x*x))+s.atan(x)/2,x,[r'x=\tan\theta,\quad\int\cos^2\theta d\theta=(\theta+\sin\theta\cos\theta)/2'],0,1,None),(21,x*x*sq(a*a-x*x),x*(2*x*x-a*a)*sq(a*a-x*x)/8+a**4*asin(x/a)/8,x,[r'x=a\sin\theta,\quad a>0',r'a^4\int\sin^2\theta\cos^2\theta d\theta=a^4(\theta/8-\sin4\theta/32)'],0,a,None),(22,sq(1-4*x*x),x*sq(1-4*x*x)/2+asin(2*x)/4,x,[r'x=\tfrac12\sin\theta,\quad\theta:\pi/6\to\pi/3',r'\tfrac12\int\cos^2\theta d\theta=(\theta+\sin\theta\cos\theta)/4'],Q(1,4),sq(3)/4,None),(23,x/sq(x*x-7),sq(x*x-7),x,[r'u=x^2-7,\quad du=2x dx',r'\tfrac12\int u^{-1/2}du=\sqrt u'],None,None,['3','4','-3']),(24,x/sq(1+x*x),sq(1+x*x),x,[r'u=1+x^2,\quad du=2x dx',r'\tfrac12\int u^{-1/2}du=\sqrt u'],None,None,None),(25,sq(1+x*x)/x,sq(1+x*x)+log(s.Abs(x)/(1+sq(1+x*x))),x,[r'x=\tan\theta,\quad\frac{\sec^3\theta}{\tan\theta}=\sec\theta\tan\theta+\csc\theta',r'\int=\sec\theta+\ln|\csc\theta-\cot\theta|'],None,None,['.3','1','-.3','-1']),(26,x/(9-25*x*x)**Q(3,2),1/(25*sq(9-25*x*x)),x,[r'u=9-25x^2,\quad du=-50x dx',r'-\tfrac1{50}\int u^{-3/2}du=u^{-1/2}/25'],0,Q(3,10),None),(27,x*x/sq(9-25*x*x),Q(9,250)*asin(5*x/3)-x*sq(9-25*x*x)/50,x,[r'x=(3/5)\sin\theta',r'\frac9{125}\int\sin^2\theta d\theta=\frac9{250}(\theta-\sin\theta\cos\theta)'],0,Q(3,5),None),(28,sq(x*x+1),(x*sq(x*x+1)+s.asinh(x))/2,x,[r'x=\tan\theta,\quad\int\sec^3\theta d\theta=\tfrac12[\sec\theta\tan\theta+\ln|\sec\theta+\tan\theta|]'],0,1,None),(29,1/sq(x*x+2*x+5),s.asinh((x+1)/2),x,[r'x^2+2x+5=(x+1)^2+4,\quad x+1=2\tan\theta',r'\int\sec\theta d\theta=\ln|\sec\theta+\tan\theta|'],None,None,None),(30,sq(x-x*x),(x-Q(1,2))*sq(x-x*x)/2+asin(2*x-1)/8,x,[r'x-x^2=1/4-(x-1/2)^2,\quad x-1/2=\tfrac12\sin\theta',r'\int_0^1\sqrt{x-x^2}dx=\tfrac14\int_{-\pi/2}^{\pi/2}\cos^2\theta d\theta'],0,1,None)]
