add(37,('a>0일 때 ∫dx/√(x²+a²)를(a)x=a tanθ,(b)x=a sinh t로 계산하고 두 표현을 비교하라.','For a>0, evaluate ∫dx/√(x²+a²) using(a)x=a tanθ and(b)x=a sinh t; compare the two forms.'),fs(r'(a)dx=a\sec^2\theta d\theta,\ \sqrt{x^2+a^2}=a\sec\theta',r'\int\sec\theta d\theta=\ln|\sec\theta+\tan\theta|=\ln(x+\sqrt{x^2+a^2})-\ln a',r'(b)dx=a\cosh tdt,\ \sqrt{x^2+a^2}=a\cosh t\Rightarrow\int dt=t',r't=\operatorname{arsinh}(x/a)=\ln[(x+\sqrt{x^2+a^2})/a]'),same(M(r'(a)\ln(x+\sqrt{x^2+a^2})+C;\quad(b)\operatorname{arsinh}(x/a)+C')),('x+√(x²+a²)>0이며 두 표현의 차 ln a는 상수이다. 두 식을 미분하여 확인했다.','x+√(x²+a²)>0; the difference ln a is constant. Differentiation verifies both forms.'),['a','b'])
add(38,('a>0일 때 ∫x²/(x²+a²)^(3/2) dx를(a)삼각치환,(b)x=a sinh t로 계산하라.','For a>0, evaluate ∫x²/(x²+a²)^(3/2) dx by(a)trigonometric substitution and(b)x=a sinh t.'),fs(r'(a)x=a\tan\theta\Rightarrow\int\frac{\tan^2\theta}{\sec\theta}d\theta=\int(\sec\theta-\cos\theta)d\theta',r'=\ln|\sec\theta+\tan\theta|-\sin\theta',r'(b)x=a\sinh t\Rightarrow\int\tanh^2t\,dt=\int(1-\operatorname{sech}^2t)dt=t-\tanh t'),same(M(r'(a)\ln(x+\sqrt{x^2+a^2})-\frac{x}{\sqrt{x^2+a^2}}+C;\quad(b)\operatorname{arsinh}(x/a)-\frac{x}{\sqrt{x^2+a^2}}+C')),('두 원시함수는 상수 차이며, 미분하면 x²/(x²+a²)^(3/2)로 돌아간다.','The primitives differ by a constant and both differentiate to x²/(x²+a²)^(3/2).'),['a','b'])
